/**
 * Generated by `createschema acquiring.AcquiringIntegrationContext 'integration:Relationship:AcquiringIntegration:PROTECT; organization:Relationship:Organization:PROTECT; settings:Json; state:Json;' --force`
 */

const { throwAuthenticationError } = require('@open-condo/keystone/apolloErrorFormatter')
const { getById } = require('@open-condo/keystone/schema')

const { CONTEXT_VERIFICATION_STATUS, CONTEXT_FINISHED_STATUS } = require('@condo/domains/acquiring/constants/context')
const { checkAcquiringIntegrationAccessRights } = require('@condo/domains/acquiring/utils/accessSchema')
const { SERVICE_PROVIDER_TYPE } = require('@condo/domains/organization/constants/common')
const { RESIDENT } = require('@condo/domains/user/constants/common')
const { SERVICE } = require('@condo/domains/user/constants/common')

/**
 * Acquiring integration context may only be read:
 * 1. Admin / support
 * 2. Organization integration manager
 * 3. Integration service account
 */
async function canReadAcquiringIntegrationContexts ({ authentication: { item: user } }) {
    if (!user) return throwAuthenticationError()
    if (user.deletedAt) return false

    if (user.isSupport || user.isAdmin) return {}

    return {
        OR: [
            {
                AND: [
                    {
                        organization: { employees_some: { user: { id: user.id }, role: { canReadPayments: true }, isBlocked: false, deletedAt: null } },
                        status_not: null,
                    },
                ],
            },
            {
                AND: [
                    {
                        organization: { employees_some: { user: { id: user.id }, role: { canReadMarketplace: true }, isBlocked: false, deletedAt: null } },
                        invoiceStatus_not: null,
                    },
                ],
            },
            { integration: { accessRights_some: { user: { id: user.id }, deletedAt: null } } },
        ],
    }
}

/**
 * Acquiring integration context may only be created by:
 * 1. Admin / support
 * 2. Organization integration manager
 * 3. Integration service user
 *
 * Acquiring integration context may only be updated by:
 * 1. Admin
 * 2. Integration service user
 */
async function canManageAcquiringIntegrationContexts ({ authentication: { item: user }, originalInput, operation, itemId, context: reqContext }) {
    if (!user) return throwAuthenticationError()
    if (user.deletedAt) return false

    if (user.isAdmin || user.isSupport) return true

    let organizationId, integrationId, context

    if (operation === 'create') {
        // get ids from input on create
        organizationId = originalInput?.organization?.connect?.id
        integrationId = originalInput?.integration?.connect?.id
        if (!organizationId || !integrationId) return false
    } else if (operation === 'update') {
        // getting ids from existing object
        if (!itemId) return false
        context = await getById('AcquiringIntegrationContext', itemId)
        if (!context) return false
        const { organization, integration } = context
        organizationId = organization
        integrationId = integration
    }

    if (!organizationId) return false

    if (user.type === SERVICE) {
        return await checkAcquiringIntegrationAccessRights(user.id, [integrationId])
    }

    return false
}

async function canManageStatusField ({ authentication: { item: user }, existingItem, operation, originalInput }) {
    // Admin / support can freely change status field
    if (user.isAdmin || user.isSupport) return true

    // Nobody else can update status field if it's on verification currently
    if (existingItem && existingItem.status === CONTEXT_VERIFICATION_STATUS) {
        return false
    }

    const integrationId = operation === 'create'
        ? originalInput?.integration?.connect?.id
        : existingItem?.integration

    // if (user.type === SERVICE) {
    //     if (!integrationId) return false
    //     return await checkAcquiringIntegrationAccessRights(user.id, [integrationId])
    // }

    // Service provider org employee should not be able to finish connecting by itself
    if ('status' in originalInput && originalInput.status === CONTEXT_FINISHED_STATUS) {
        const orgId = operation === 'create' ? originalInput?.organization?.connect?.id : existingItem?.organization
        if (!orgId) {
            return false
        }
        const org = await getById('Organization', orgId)

        return Boolean(org && org.type !== SERVICE_PROVIDER_TYPE)
    }

    return true
}

async function canManageReasonAndFeeFields ({ authentication: { item: user } }) {
    // Admin / support can freely change reason and fee fields
    if (user.isAdmin || user.isSupport) return true

    // RESIDENT users are forbidden from changing reason and fee fields
    return user.type !== RESIDENT
}


/*
  Rules are logical functions that used for list access, and may return a boolean (meaning
  all or no items are available) or a set of filters that limit the available items.
*/
module.exports = {
    canReadAcquiringIntegrationContexts,
    canManageAcquiringIntegrationContexts,
    canManageStatusField,
    canManageReasonAndFeeFields,
}
